//! 🔊️ Writes exact binary32 sample words, channel order, provenance and ordered tags directly.
use semio_framework_value::{ValueError,ValueRefusalKind};
use crate::standards::v1::subsets::audio::schema::snapshot::{SemioAudioSnapshot,SemioAudioChannel,SemioAudioTag};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(crate) fn encode(snapshot:&SemioAudioSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode(encoding,"semio stdio.semio.audio.dsl v1\n","stdio.semio.audio.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn channel(value:&SemioAudioChannel,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.list(&value.samples,encoding,|writer,value|{if encoding==SnapshotEncoding::Binary{writer.bytes(&value.to_bits().to_le_bytes())}else{const DIGITS:&[u8;16]=b"0123456789abcdef";let mut word=[0;8];for(index,byte)in word.iter_mut().enumerate(){*byte=DIGITS[((value.to_bits()>>((7-index)*4))&15)as usize];}writer.bytes(&word)}})}
fn tag(value:&SemioAudioTag,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.key,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.value,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioAudioSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nsampleRate=",encoding)?;if encoding==SnapshotEncoding::Binary{writer.bytes(&snapshot.sample_rate.to_le_bytes())?;}else{writer.integer(u64::from(snapshot.sample_rate),encoding)?;}writer.delimiter(b"\nformat=",encoding)?;if encoding==SnapshotEncoding::Binary{writer.byte(crate::standards::v1::subsets::audio::io::binary::snapshot::format_tag(snapshot.format))?;}else{writer.bytes(crate::standards::v1::subsets::audio::io::text::snapshot::enc_format(snapshot.format).as_bytes())?;}writer.delimiter(b"\nchannels=",encoding)?;writer.list(&snapshot.channels,encoding,|writer,value|channel(value,writer,encoding))?;writer.delimiter(b"\ntags=",encoding)?;writer.list(&snapshot.tags,encoding,|writer,value|tag(value,writer,encoding))}
